#!/usr/bin/env bash
# GENERATED by harness-kit — do not edit.
# Perfil: python-unittest
#
# Verificación e inicialización del entorno. Lo ejecuta el agente al
# COMENZAR una sesión y antes de declarar cualquier feature como `done`.
# Si falla, la sesión no debe avanzar.

set -u
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[0;33m'
NC='\033[0m'

ok()   { printf "${GREEN}[OK]${NC}    %s\n" "$1"; }
warn() { printf "${YELLOW}[WARN]${NC}  %s\n" "$1"; }
fail() { printf "${RED}[FAIL]${NC}  %s\n" "$1"; }

EXIT_CODE=0

echo "── 1. Entorno: arnés y contenedor ────────────────────"

if ! command -v python3 >/dev/null 2>&1; then
  fail "python3 no está instalado (lo necesita el arnés)"
  exit 1
fi
ok "python3 -> $(python3 --version)"

PY_VERSION_OK=$(python3 -c 'import sys; print(int(sys.version_info >= (3, 9)))')
if [ "$PY_VERSION_OK" != "1" ]; then
  fail "se requiere Python >= 3.9 para el arnés"
  exit 1
fi
ok "versión de Python compatible"

if ! command -v docker >/dev/null 2>&1; then
  fail "docker no está instalado (el stack corre en contenedor)"
  exit 1
fi
if ! docker compose version >/dev/null 2>&1; then
  fail "docker compose no está disponible"
  exit 1
fi
ok "docker compose disponible"

echo ""
echo "── 2. Archivos base del arnés ─────────────────────────"

for f in AGENTS.md harness.config.json feature_list.json project-spec.md \
         progress/current.md harness/bin/harness.py \
         docs/architecture.md docs/conventions.md docs/verification.md; do
  if [ ! -f "$f" ]; then
    fail "falta archivo base: $f"
    EXIT_CODE=1
  else
    ok "existe $f"
  fi
done

echo ""
echo "── 3. Estado, specs y approvals ───────────────────────"

if [ -f harness/bin/harness.py ]; then
  if python3 harness/bin/harness.py validate; then
    ok "harness.py validate en verde"
  else
    fail "harness.py validate falló"
    EXIT_CODE=1
  fi
else
  fail "no se puede validar: falta harness/bin/harness.py"
fi

echo ""
echo "── 4. Documentos del proyecto ─────────────────────────"

for f in docs/architecture.md docs/conventions.md docs/verification.md; do
  if [ -f "$f" ] && grep -q "TODO" "$f"; then
    if [ "$f" = "docs/architecture.md" ]; then
      warn "$f contiene TODO: next devolverá la fase architecture; ejecuta /architecture"
    else
      warn "$f todavía contiene TODO: el judge revisará contra un estándar incompleto"
    fi
  fi
done

echo ""
echo "── 5. Tests (contenedor) ──────────────────────────────"

if [ -d tests ] && find tests -name 'test_*.py' -print -quit | grep -q .; then
  if ! docker compose build --quiet; then
    fail "no se pudo construir la imagen; revisa Dockerfile y compose.yaml"
    EXIT_CODE=1
  elif python3 harness/bin/run_verb.py test; then
    ok "todos los tests pasan (contenedor)"
  else
    fail "hay tests rotos en el contenedor"
    EXIT_CODE=1
  fi
else
  warn "no hay tests todavía (tests/test_*.py)"
fi

echo ""
echo "── 6. Contrato del stack ──────────────────────────────"

if python3 harness/bin/stack_check.py; then
  ok "contrato del stack (check/build/test/mutation/clean)"
else
  fail "el stack no cumple el contrato; ver stack_check.py"
  EXIT_CODE=1
fi

echo ""
echo "── 7. Resumen ─────────────────────────────────────────"

if [ $EXIT_CODE -eq 0 ]; then
  ok "entorno listo"
else
  fail "entorno NO listo; resuelve los errores antes de avanzar"
fi

exit $EXIT_CODE
